    public class StressTestScene : MonoBehaviour
    {
        // Cache de referências e buffers reutilizáveis para evitar alocações de GC no loop principal
        [SerializeField] private Transform[] targetTransforms;
        private Vector3[] cachedPositions;
        private int transformCount;

        private void Awake()
        {
            if (targetTransforms != null)
            {
                transformCount = targetTransforms.Length;
                cachedPositions = new Vector3[transformCount];
            }
        }

        private void Update()
        {
            if (targetTransforms == null || transformCount == 0) return;

            float deltaTime = Time.deltaTime;

            // Loop otimizado sem alocação de memória (GC Alloc = 0 bytes)
            for (int i = 0; i < transformCount; i++)
            {
                Transform t = targetTransforms[i];
                if (t != null)
                {
                    Vector3 pos = t.position;
                    pos.y += Mathf.Sin(Time.time + i) * deltaTime;
                    t.position = pos;
                }
            }
        }
    }
}

