    public class StressTestScene : MonoBehaviour
    {
        [Header("Configurações de Processamento")]
        [SerializeField] private int maxElements = 1000;
        [SerializeField] private float updateInterval = 0.1f;

        // Buffers pré-alocados para evitar garbage collection contínuo
        private Vector3[] positionsBuffer;
        private float timer;

        private void Awake()
        {
            // Alocação única de memória na inicialização
            positionsBuffer = new Vector3[maxElements];
        }

        private void Update()
        {
            // Throttling: distribui o processamento em intervalos controlados em vez de todo frame
            timer += Time.deltaTime;
            if (timer < updateInterval)
            {
                return;
            }
            timer = 0f;

            ExecuteOptimizedProcessing();
        }

        private void ExecuteOptimizedProcessing()
        {
            // Itera diretamente sobre buffers já existentes sem alocações dinâmicas na heap
            int length = positionsBuffer.Length;
            for (int i = 0; i < length; i++)
            {
                positionsBuffer[i] += Vector3.forward * Time.deltaTime;
            }
        }
    }
