using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestSceneOptimized : MonoBehaviour
    {
        [SerializeField] private int _elementCount = 100000;
        private NativeArray<float> _dataArray;
        private JobHandle _jobHandle;

        private struct ComputeJob : IJobParallelFor
        {
            public float TimeOffset;
            public NativeArray<float> Results;

            public void Execute(int index)
            {
                Results[index] = math.sin(index + TimeOffset);
            }
        }

        private void Awake()
        {
            _dataArray = new NativeArray<float>(_elementCount, Allocator.Persistent);
        }

        private void Update()
        {
            _jobHandle.Complete();

            var job = new ComputeJob
            {
                TimeOffset = Time.time,
                Results = _dataArray
            };

            _jobHandle = job.Schedule(_dataArray.Length, 64);
        }

        private void LateUpdate()
        {
            _jobHandle.Complete();
        }

        private void OnDestroy()
        {
            _jobHandle.Complete();
            if (_dataArray.IsCreated)
            {
                _dataArray.Dispose();
            }
        }
    }
}

