    public static class SceneObjectRegistry
    {
        private static readonly List<GameObject> RegisteredObjects = new List<GameObject>(1024);

        public static void Register(GameObject go)
        {
            if (go != null && !RegisteredObjects.Contains(go))
            {
                RegisteredObjects.Add(go);
            }
        }

        public static void Unregister(GameObject go)
        {
            if (go != null)
            {
                RegisteredObjects.Remove(go);
            }
        }

        public static IReadOnlyList<GameObject> AllObjects => RegisteredObjects;
    }
